package com.mediconnect.bootstrap;
import java.util.List; import com.mediconnect.specialty.domain.SpecialtyEntity; import com.mediconnect.specialty.infrastructure.SpecialtyRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class ReferenceDataInitializer implements CommandLineRunner { private final SpecialtyRepository specialtyRepository; public ReferenceDataInitializer(SpecialtyRepository specialtyRepository){this.specialtyRepository=specialtyRepository;} @Override @Transactional public void run(String... args){List<SpecialtySeed> seeds=List.of(new SpecialtySeed("Cardiología","Diagnóstico y tratamiento de enfermedades cardiovasculares."),new SpecialtySeed("Pediatría","Atención médica integral de niños y adolescentes."),new SpecialtySeed("Dermatología","Diagnóstico y tratamiento de enfermedades de la piel."),new SpecialtySeed("Medicina General","Atención primaria y evaluación médica general."));seeds.forEach(seed->specialtyRepository.findByNameIgnoreCase(seed.name()).orElseGet(()->specialtyRepository.save(new SpecialtyEntity(seed.name(),seed.description()))));} private record SpecialtySeed(String name,String description){} }
